<script lang="ts">
  import { page } from '$app/state';
  import { goto } from '$app/navigation';
  import { onMount } from 'svelte';
  import { Button } from '$lib/components/ui/button';
  import { Input } from '$lib/components/ui/input';
  import { Textarea } from '$lib/components/ui/textarea';
  import { Compass, Clapperboard, FolderOpen, Coins, Radio, ChartNoAxesCombined, Settings, ArrowUpRight, ArrowRight, Plus, Play, Film, LogOut, LoaderCircle, Sparkles, Check, ShieldCheck, Heart, ListVideo, Users, Image, SlidersHorizontal, Crown } from '@lucide/svelte';
  import { request, CloudError } from './api';
  import type { Project, Quote } from './generated';
  import './cloud.css';
  import VideoPlayer from './VideoPlayer.svelte';
  import Studio from './Studio.svelte';
  import OriginalStudio from './OriginalStudio.svelte';
  import AuthForm from './AuthForm.svelte';
  import GenerationJobs from './GenerationJobs.svelte';
  let user = $state<any>(null);
  let sessionKnown=$state(false);
  let ready = $state(!!page.data.cloudPublic);
  let loading = $state(!page.data.cloudPublic);
  let loadFailed = $state(false);
  let busy = $state(false);
  let error = $state('');
  let notice = $state('');
  let data = $state<any>(page.data.cloudPublic || {});
  let projects = $state<Project[]>([]);
  let jobs = $state<any[]>([]);
  let email = $state(''); let password = $state(''); let name = $state(''); let handle = $state('');
  let prompt = $state(''); let duration = $state('10'); let ratio = $state('16:9'); let projectId = $state('');
  let projectName = $state(''); let projectDescription = $state('');
  let quote = $state<Quote | null>(null); let quoteKey = '';
  let channelName = $state(''); let channelDescription = $state('');
  let title = $state(''); let description = $state(''); let jobId = $state(''); let visibility = $state('private'); let audience = $state('free');
  let playback = $state('');
  let premiumCheckoutKey='';
  function subscribePremium(){if(!user){void goto('/login');return;}premiumCheckoutKey ||= crypto.randomUUID();void action(async()=>{const result=await request('/premium/checkout',{},'POST',{'Idempotency-Key':premiumCheckoutKey});window.location.assign(result.url);});}
  let payout = $state<any>({}); let payoutCountry = $state('');
  let reportReason = $state(''); let showReport = $state(false); let followed = $state(false);
  const creditCheckoutKeys = new Map<string,string>();
  function buyCredits(packId:string) {
    let key=creditCheckoutKeys.get(packId);
    if(!key){key=crypto.randomUUID();creditCheckoutKeys.set(packId,key);}
    void action(async()=>{const result=await request('/billing/checkout',{pack_id:packId},'POST',{'Idempotency-Key':key!});window.location.assign(result.url);});
  }
  let token = $state(''); let developmentToken = $state('');
  const path = $derived(page.url.pathname);
  const recoveryPage = $derived(['/forgot-password','/reset-password','/verify-email'].includes(path));
  const authPage = $derived(path === '/login' || path === '/register' || recoveryPage);
  const signInPage=$derived(path==='/login'||path==='/register');
  const canvasPage=$derived(['/','/studio','/scenes','/characters','/assets'].includes(path));
  const displayAuth=$derived(signInPage||(canvasPage&&sessionKnown&&!user));
  const publicPage = $derived(path==='/discover'||path.startsWith('/watch/')||path.startsWith('/channels/')||path==='/premium'||path==='/memberships');
  const createNav=[{url:'/create',label:'Create video',icon:Clapperboard}];
  const outputNav=[{url:'/render',label:'My videos',icon:Film}];
  const advancedNav=[{url:'/',label:'Studio',icon:Clapperboard},{url:'/scenes',label:'Scenes',icon:ListVideo},{url:'/characters',label:'Characters',icon:Users},{url:'/assets',label:'Assets',icon:Image},{url:'/workspace',label:'Project details',icon:FolderOpen}];
  const systemNav=[{url:'/discover',label:'Discover',icon:Compass},{url:'/credits',label:'Credits',icon:Coins},{url:'/premium',label:'Premium',icon:Crown},{url:'/channel',label:'Channel',icon:Radio},{url:'/earnings',label:'Earnings',icon:ChartNoAxesCombined},{url:'/settings',label:'Settings',icon:SlidersHorizontal}];
  const mobileNav=[{url:'/projects',label:'Projects',icon:FolderOpen},...createNav,...outputNav,...advancedNav,...systemNav];
  const active=(url:string)=>url==='/' ? path==='/'||path==='/studio' : path.startsWith(url);
  const titles: Record<string,string> = {'/':'Studio','/discover':'Discover','/create':'Create video','/projects':'Projects','/credits':'Credits & billing','/channel':'Your channel','/earnings':'Creator earnings','/studio':'Advanced studio','/settings':'Account settings','/memberships':'Premium','/premium':'Premium','/render':'My videos','/scenes':'Scenes','/characters':'Characters','/assets':'Assets'};
  const list = (value:any):any[] => Array.isArray(value) ? value : value?.items || value?.videos || value?.projects || value?.jobs || [];
  const money = (cents:number | undefined, currency = 'USD') => cents == null ? '—' : new Intl.NumberFormat('en-US',{style:'currency',currency}).format(cents/100);
  const date = (value:string) => value ? new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}) : '—';
  onMount(() => {
    token = page.url.searchParams.get('token') || '';
    request('/me').then(v => user = v.user || v).catch(e => {
      if (!(e instanceof CloudError && e.status === 401)) error = e.message;
    }).finally(() => {ready=true;sessionKnown=true;});

  });
  $effect(() => { const incoming=page.url.searchParams.get('token'); if (recoveryPage && incoming) token=incoming; });
  $effect(() => { if (ready) { const current = path; if (page.data.cloudPath === current && page.data.cloudPublic) { data = page.data.cloudPublic; loading = false; } else void load(current); } });
  async function load(current:string) {
    loading = true; loadFailed = false; error = ''; notice = ''; data = {}; playback = ''; quote = null; showReport = false; reportReason = ''; followed = false;
    if (authPage) { loading = false; return; }
    if (!user && !publicPage) { loading = false; return; }
    try {
      if (canvasPage) data = {};
      else if(current==='/discover')data={videos:list(await request('/feed'))};
      else if (current === '/projects') data = {projects:list(await request('/projects'))};
      else if (current === '/create') { const [p,j] = await Promise.all([request('/projects'),request('/jobs')]); projects = list(p); jobs = list(j); }
      else if (current === '/credits') { const [balance,packs] = await Promise.all([request('/credits'),request('/billing/packs')]); data = {...balance,...packs}; }
      else if (current === '/channel') { const [channel,generations] = await Promise.all([request('/channel'),request('/jobs')]);data=channel; jobs=list(generations); channelName = data.channel?.name || data.name || ''; channelDescription = data.channel?.description || data.description || ''; }
      else if (current === '/earnings') { const [earnings,analytics,account] = await Promise.all([request('/creator/earnings'), request('/creator/analytics'),request('/creator/payout-account')]); data = {...earnings,analytics}; payout=account;payoutCountry=account.country || ''; }
      else if (current === '/premium'||current === '/memberships') data=await request('/premium');
      else if(current==='/render')jobs=list(await request('/jobs'));
      else if (current.startsWith('/watch/')) { data = await request(`/videos/${encodeURIComponent(current.split('/')[2])}`); }
      else if (current.startsWith('/channels/')) data = await request(`/channels/${encodeURIComponent(current.split('/')[2])}`);
    } catch(e) { error = (e as Error).message; loadFailed = true; } finally { loading = false; }
  }
  async function action(fn:()=>Promise<void>) { busy = true; error = ''; notice = ''; try { await fn(); } catch(e) { error = (e as Error).message; } finally { busy = false; } }
  async function authenticate(fields:{email:string;password:string;name:string;handle:string}) { await action(async () => { await request(path === '/register' ? '/auth/register' : '/auth/login', path === '/register' ? fields : {email:fields.email,password:fields.password}); user = await request('/me'); await goto('/'); }); }
  function getQuote() { void action(async () => { quote = await request('/generation/quotes',{prompt,duration:Number(duration),aspect_ratio:ratio,project_id:projectId || undefined}); quoteKey = crypto.randomUUID(); }); }
  function generate() { const quoteId=quote?.id; if(!quoteId)return; void action(async () => { await request('/generation/jobs',{quote_id:quoteId},'POST',{'Idempotency-Key':quoteKey}); quote = null; jobs = list(await request('/jobs')); notice = 'Generation submitted. Your progress is saved here.'; }); }
  function createProject() { void action(async () => { await request('/projects',{name:projectName,description:projectDescription}); projectName = ''; projectDescription = ''; data = {projects:list(await request('/projects'))}; notice = 'Project created.'; }); }
  function publish() { void action(async () => { const video = await request('/videos',{job_id:jobId,title,description,visibility,audience}); await request(`/videos/${video.id}/publish`,{}); notice = visibility === 'private' ? 'Private video saved and submitted for processing.' : 'Video submitted for publishing.'; data = await request('/channel'); }); }
</script>

<svelte:head><title>{titles[path] || (authPage ? 'Welcome' : data.title || data.channel?.name || data.name || 'Watch')} · VideoFlow</title>{#if publicPage}<link rel="canonical" href={page.url.origin + path}/><meta property="og:title" content={`${data.title || data.channel?.name || data.name || titles[path] || 'VideoFlow'} · VideoFlow`}/><meta property="og:description" content={data.description || data.channel?.description || 'VideoFlow video studio.'}/>{/if}<meta name="description" content="Create your next story with VideoFlow. Your video studio, channel, and creative community." /></svelte:head>
{#if canvasPage&&!sessionKnown}
  <div class="flex h-screen items-center justify-center gap-2 bg-background text-sm text-muted-foreground" role="status"><LoaderCircle class="size-4 animate-spin"/>Loading VideoFlow…</div>
{:else if displayAuth}
  <AuthForm mode={path==='/register'?'register':'login'} {busy} {error} {notice} onSubmit={authenticate}/>
{:else}
<div class="cloud-app flex h-screen min-w-0 flex-col bg-background text-foreground md:flex-row">
  <nav aria-label="Primary" class="flex shrink-0 items-center gap-1 overflow-x-auto border-b border-border px-2 py-1.5 md:hidden">{#each mobileNav as item}<a href={item.url} aria-current={active(item.url)?'page':undefined} class="shrink-0 rounded-md px-2 py-1.5 text-xs hover:bg-accent">{item.label}</a>{/each}</nav>
  <aside class="hidden w-48 shrink-0 flex-col overflow-y-auto border-r border-border p-3 md:flex">
    <a href="/" class="px-2 pt-3 pb-1 text-sm font-semibold tracking-wide">VideoFlow</a>
    <a href="/projects" class="mb-1 flex items-center gap-2 rounded-md px-2 py-1.5 text-xs hover:bg-accent {active('/projects')?'bg-accent font-medium':'text-muted-foreground'}"><FolderOpen class="size-3.5 shrink-0"/><span class="truncate">Projects</span></a>
    {#each [{title:'Create',items:createNav},{title:'Output',items:outputNav},{title:'Advanced',items:advancedNav},{title:'System',items:systemNav}] as group}<div class="px-2 pt-4 pb-1 text-[10px] tracking-wider text-muted-foreground/70 uppercase">{group.title}</div>{#each group.items as item}<a href={item.url} aria-current={active(item.url)?'page':undefined} class="flex items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent {active(item.url)?'bg-accent font-medium':'text-muted-foreground'}"><item.icon class="size-4"/>{item.label}</a>{/each}{/each}
    <div class="mt-auto border-t border-border pt-3">{#if user}<div class="flex items-center justify-between gap-2 px-2 text-xs"><span class="truncate text-muted-foreground" title={user.email}>{user.name || user.email}</span><button aria-label="Sign out" class="rounded p-1 hover:bg-accent" onclick={()=>action(async()=>{await request('/auth/logout',{});user=null;await goto('/login');})}><LogOut class="size-3.5"/></button></div>{:else}<Button href="/login" size="sm" variant="outline" class="w-full">Sign in</Button>{/if}</div>
  </aside>
  <div class="cloud-body min-h-0 min-w-0 flex-1 overflow-hidden">
    {#if !canvasPage}<header class="cloud-topbar"><span>{titles[path] || 'VideoFlow'}</span><div class="flex items-center gap-4"><a href="/premium" class="inline-flex items-center gap-1.5 text-xs text-muted-foreground"><Crown class="size-3.5"/>Premium</a>{#if !user}<Button href="/login" variant="outline" size="sm">Sign in</Button>{/if}</div></header>{/if}
    <main class="cloud-main" class:cloud-canvas-main={canvasPage}>
      {#if error}<div class="cloud-alert" role="alert"><span>{error}</span><button onclick={() => load(path)}>Try again</button></div>{/if}
      {#if notice}<div class="cloud-notice" role="status"><Check size={17}/>{notice}</div>{/if}
      {#if !ready || loading}<div class="cloud-loading" role="status"><LoaderCircle class="animate-spin" size={25}/><span>Opening your creative space…</span></div>
      {:else if loadFailed}<div class="cloud-empty"><Film size={35}/><h1>Let's try that again.</h1><p>This page couldn't be loaded. Your saved work is still in your account.</p><Button onclick={()=>load(path)}>Reload page</Button></div>
      {:else if recoveryPage}
        <form class="auth-form" style="margin:30px auto" onsubmit={(e)=>{e.preventDefault();action(async()=>{ const endpoint=path === '/forgot-password' ? '/auth/forgot-password' : path === '/verify-email' ? '/auth/verify-email' : '/auth/reset-password'; const result=await request(endpoint,path === '/forgot-password' ? {email} : path === '/verify-email' ? {token} : {token,password});developmentToken=result.development_token || '';if(path === '/verify-email' && user)user=await request('/me');notice=path === '/forgot-password' ? 'If this email is registered, recovery instructions have been sent.' : path === '/verify-email' ? 'Email verified. You can return to your studio.' : 'Password reset. Sign in with your new password.';});}}>
          <span class="eyebrow">YOUR ACCOUNT</span><h2>{path === '/forgot-password' ? 'Reset your password.' : path === '/verify-email' ? 'Verify your email.' : 'A fresh start.'}</h2>
          {#if path === '/forgot-password'}<label for="recovery-email">Email address</label><Input id="recovery-email" type="email" bind:value={email} required autocomplete="email"/>{:else}<label for="token">Token from your email</label><Input id="token" bind:value={token} required autocomplete="one-time-code"/>{/if}
          {#if path === '/reset-password'}<label for="new-password">New password</label><Input id="new-password" type="password" bind:value={password} minlength={12} required autocomplete="new-password"/>{/if}
          {#if developmentToken}<p class="field-help">Local development token: <code>{developmentToken}</code></p><a href="/reset-password">Enter reset token</a>{/if}
          <Button type="submit" disabled={busy} class="w-full">Continue <ArrowRight size={16}/></Button><p class="auth-switch"><a href="/login">Back to sign in</a></p>
        </form>
      {:else if !user && !publicPage}
        <div class="cloud-empty"><ShieldCheck size={38}/><h1>Your studio is waiting.</h1><p>Sign in to create videos, manage projects, and grow your channel.</p><Button href="/login">Sign in <ArrowRight size={16}/></Button><a href="/register">Create an account</a></div>
      {:else if canvasPage}
        <OriginalStudio/>
      {:else if path==='/discover'}
        <div class="page-heading"><h1>Discover</h1><p>Public videos from VideoFlow creators.</p></div>{#if data.videos?.length}<div class="video-grid">{#each data.videos as video}<a class="video-tile" href={`/watch/${video.id}`}><div class="video-image">{#if video.thumbnail_url}<img src={video.thumbnail_url} alt="" loading="lazy"/>{:else}<Film class="size-8"/>{/if}</div><h3>{video.title}</h3><p class="subtle">{video.channel_name || video.handle || 'VideoFlow creator'}</p></a>{/each}</div>{:else}<div class="cloud-empty compact"><Film class="size-8"/><h2>No public videos yet</h2><p>Published public videos will appear here.</p><Button variant="outline" href="/create">Create video</Button></div>{/if}
      {:else if path === '/create'}
        <div class="page-heading"><span class="eyebrow">FROM THOUGHT TO FRAME</span><h1>Create video</h1><p>Describe your video. Review the cost. Bring it to life.</p></div><div class="story-entry"><div><span class="eyebrow">MORE THAN A SINGLE CLIP</span><h2>Have a whole story in mind?</h2><p>Plan a screenplay, generate its scenes, and assemble a complete video in your project storyboard.</p></div><Button variant="outline" href={`/studio?tab=storyboard${projectId ? '&project='+encodeURIComponent(projectId) : ''}`}>Open story-to-video <ArrowUpRight size={16}/></Button></div><div class="section-heading clip-heading"><h2>Or start with a single clip</h2></div><div class="creation-layout"><form class="cloud-panel create-form" onsubmit={(e)=>{e.preventDefault();getQuote();}}><label for="prompt" class="strong-label">The idea</label><Textarea id="prompt" bind:value={prompt} oninput={()=>quote=null} placeholder="A quiet coastal town at sunrise. A cyclist follows the winding road as the first light reaches the sea…" required minlength={10} rows={7}/><p class="field-help">Set the scene, describe the action, and tell us how it should feel.</p><div class="form-grid"><div><label for="duration">Duration</label><select id="duration" bind:value={duration} onchange={()=>quote=null}><option value="5">5 seconds</option><option value="10">10 seconds</option><option value="15">15 seconds</option><option value="30">30 seconds</option></select></div><div><label for="ratio">Frame</label><select id="ratio" bind:value={ratio} onchange={()=>quote=null}><option>16:9</option><option>9:16</option><option>1:1</option></select></div></div><label for="project">Project</label><select id="project" bind:value={projectId} onchange={()=>quote=null}><option value="">No project</option>{#each projects as project}<option value={project.id}>{project.name}</option>{/each}</select><div class="form-footer"><span><ShieldCheck size={15}/>Private until you publish</span><Button type="submit" disabled={busy || prompt.length < 10}>Review credit cost <ArrowRight size={15}/></Button></div>{#if quote}<div class="quote-box"><div><strong>{quote.credits} credits</strong><p>Quote expires {new Date(quote.expires_at).toLocaleTimeString()}. Credits are reserved when you confirm.</p></div><Button type="button" disabled={busy || Date.parse(quote.expires_at) < Date.now()} onclick={generate}>Confirm generation</Button></div>{/if}</form><aside class="creative-guide"><span class="eyebrow">A STRONG START</span><h2>Give your idea<br/>a little direction.</h2><ol><li><span>01</span><div><strong>Build a world</strong><p>Where are we? A place, a time of day, a feeling.</p></div></li><li><span>02</span><div><strong>Find the movement</strong><p>Describe what happens, from subject to camera.</p></div></li><li><span>03</span><div><strong>Make it yours</strong><p>Natural light, a cinematic mood, or something unexpected.</p></div></li></ol><div class="guide-foot"><Coins size={17}/><p>You see the credit cost before any generation starts.</p></div></aside></div><GenerationJobs {jobs} onrefresh={async()=>{jobs=list(await request('/jobs'));}}/>
      {:else if path === '/workspace'}
        <Studio/>
      {:else if path === '/render'}
        <div class="page-heading"><h1>My videos</h1><p>Generation progress and completed outputs.</p></div><GenerationJobs {jobs} onrefresh={async()=>{jobs=list(await request('/jobs'));}}/>
      {:else if path === '/projects'}
        <div class="page-heading"><span class="eyebrow">YOUR WORK, TOGETHER</span><h1>Projects</h1><p>Keep your creative work organized in private projects.</p></div><div class="projects-layout"><section>{#if data.projects?.length}<div class="project-grid">{#each data.projects as project}<article class="cloud-panel project-card"><FolderOpen size={26}/><h2>{project.name}</h2><p>{project.description || 'A fresh space for your next video.'}</p><small>Created {date(project.created_at)}</small><Button variant="outline" href={`/studio?project=${project.id}`}>Open studio <ArrowUpRight size={14}/></Button></article>{/each}</div>{:else}<div class="cloud-empty compact"><FolderOpen size={35}/><h2>Big ideas need a little space.</h2><p>Create your first project to keep your work together.</p></div>{/if}</section><form class="cloud-panel" onsubmit={(e)=>{e.preventDefault();createProject();}}><h2>New project</h2><label for="project-name">Project name</label><Input id="project-name" bind:value={projectName} placeholder="My next great idea" required maxlength={100}/><label for="project-description">Description <span class="subtle">(optional)</span></label><Textarea id="project-description" bind:value={projectDescription} rows={4}/><Button type="submit" disabled={busy || !projectName.trim()}><Plus size={16}/>Create project</Button></form></div>
      {:else if path === '/credits'}
        <div class="page-heading"><span class="eyebrow">FUEL YOUR NEXT IDEA</span><h1>Credits & billing</h1><p>Credits power your generations. Your confirmed balance is always here.</p></div>{#if data.restricted || data.debt > 0}<div class="cloud-alert" role="alert"><div><strong>{data.restricted ? 'Generation is restricted on your account.' : 'Your account has an outstanding credit balance.'}</strong>{#if data.debt > 0}<p>Outstanding debt: {data.debt.toLocaleString()} credits.</p>{/if}<p>Review your credit activity for payment reversals and adjustments.</p></div></div>{/if}<div class="balance-strip"><div><span>Available credits</span><strong>{data.available ?? '—'}<Coins size={25}/></strong></div><div><span>Reserved for generation</span><strong>{data.reserved ?? '—'}</strong></div><p>Generation credits are used in the studio and cannot be withdrawn as cash.</p></div><div class="section-heading"><h2>Top up your creativity</h2></div>{#if !data.checkout_enabled}<div class="info-banner"><Coins size={20}/><div><strong>Credit purchases are not open yet.</strong><p>Checkout will become available when pricing and payments are configured.</p></div></div>{/if}<div class="pack-grid">{#each data.packs || [] as pack}<article class="cloud-panel"><span class="eyebrow">{pack.name}</span><h2>{pack.credits.toLocaleString()} <small>credits</small></h2><p class="pack-price">{money(pack.price_cents,pack.currency)}</p><Button disabled={!data.checkout_enabled || busy} onclick={()=>buyCredits(pack.id)}>Buy credits <ArrowUpRight size={15}/></Button></article>{/each}</div><section class="jobs-section"><h2>Credit activity</h2>{#if data.transactions?.length}<div class="record-list">{#each data.transactions as transaction}<div class="record"><Coins size={18}/><div><strong>{transaction.description || transaction.kind}</strong><small>{date(transaction.created_at)}</small></div><strong>{transaction.amount ?? transaction.credits}</strong></div>{/each}</div>{:else}<p class="quiet-empty">Purchases, reservations, and refunds will appear here.</p>{/if}</section>
      {:else if path === '/channel'}
        <div class="page-heading"><span class="eyebrow">YOUR CORNER OF VIDEOFLOW</span><h1>Your channel</h1><p>Shape your channel and choose what you share with the world.</p></div><div class="channel-banner"><span class="channel-avatar">{(channelName || user.name || 'V').slice(0,1).toUpperCase()}</span><div><h2>{channelName || user.name}</h2><p>@{data.channel?.handle || data.handle || user.handle}</p></div><a href={`/channels/${data.channel?.handle || data.handle || user.handle}`}>View channel <ArrowUpRight size={16}/></a></div><div class="projects-layout"><form class="cloud-panel" onsubmit={(e)=>{e.preventDefault();action(async()=>{await request('/channel',{name:channelName,description:channelDescription},'PATCH');notice='Channel updated.';});}}><h2>Channel details</h2><label for="channel-name">Channel name</label><Input id="channel-name" bind:value={channelName} required/><label for="channel-description">About your channel</label><Textarea id="channel-description" bind:value={channelDescription} rows={4}/><Button disabled={busy} type="submit">Save changes</Button></form><form class="cloud-panel" onsubmit={(e)=>{e.preventDefault();publish();}}><h2>Share a finished video</h2><label for="job">Completed generation</label><select id="job" bind:value={jobId} required><option value="">Choose a generation</option>{#each jobs.filter(j=>['completed','succeeded','complete'].includes(j.status)) as job}<option value={job.id}>{job.prompt || job.name || job.id}</option>{/each}</select><label for="video-title">Title</label><Input id="video-title" bind:value={title} required/><label for="video-description">Description</label><Textarea id="video-description" bind:value={description}/><div class="form-grid"><div><label for="visibility">Visibility</label><select id="visibility" bind:value={visibility}><option value="private">Private</option><option value="unlisted">Unlisted</option><option value="public">Public</option></select></div><div><label for="audience">Audience</label><select id="audience" bind:value={audience}><option value="free">Free content</option><option value="members">Premium content</option></select></div></div><p class="field-help">Published videos show an AI-generated disclosure. Playback is available after processing and review.</p><Button type="submit" disabled={busy || !jobId || !title}>{visibility === 'private' ? 'Save private video' : 'Publish video'}<ArrowUpRight size={15}/></Button></form></div><section class="jobs-section"><h2>Your publications</h2>{#each data.videos || [] as video}<div class="record"><Film size={18}/><div><strong>{video.title}</strong><small>{video.visibility} · {video.status}</small></div><a href={`/watch/${video.id}`}>View <ArrowUpRight size={14}/></a></div>{:else}<p class="quiet-empty">Your published and private videos will appear here.</p>{/each}</section>
      {:else if path === '/earnings'}
        <div class="page-heading"><span class="eyebrow">CREATOR BUSINESS</span><h1>Creator earnings</h1><p>Track your audience and confirmed creator earnings.</p></div><div class="metric-grid">{#each [{label:'Validated views',value:data.analytics?.views},{label:'Watch minutes',value:data.analytics?.watch_minutes},{label:'Followers',value:data.analytics?.followers},{label:'Published videos',value:data.analytics?.videos}] as metric}<div><span>{metric.label}</span><strong>{metric.value ?? '—'}</strong></div>{/each}</div><div class="section-heading"><h2>Earnings</h2><span class="subtle">{data.currency || 'USD'}</span></div><div class="balance-strip"><div><span>Available</span><strong>{money(data.available_cents,data.currency)}</strong></div><div><span>Pending</span><strong>{money(data.pending_cents,data.currency)}</strong></div><div><span>Paid to date</span><strong>{money(data.paid_cents,data.currency)}</strong></div></div>{#if !data.rewards_enabled}<div class="info-banner"><ShieldCheck size={21}/><div><strong>Creator rewards are not enabled.</strong><p>Eligibility, rewards policy, and payouts must be approved before earnings can be activated. There is no guaranteed payment per view.</p></div></div>{/if}<section class="cloud-panel payout-panel"><div><span class="eyebrow">GET READY TO EARN</span><h2>Payout account</h2><p>{payout.configured ? `Account connected${payout.country ? ' in ' + payout.country : ''}.` : 'Connect an eligible account to complete identity and payment verification.'}</p><p class="field-help">{payout.payouts_enabled ? 'Payment provider account verified.' : 'Payment provider verification is incomplete.'} {payout.cash_payouts_enabled ? 'Cash payouts are enabled.' : 'Cash payouts are not enabled. Connecting an account does not activate payouts.'}</p></div><form onsubmit={(e)=>{e.preventDefault();action(async()=>{const result=await request('/creator/payout-account',{country:payoutCountry.toUpperCase()});window.location.assign(result.url);});}}><label for="payout-country">Country code</label><Input id="payout-country" bind:value={payoutCountry} placeholder="e.g. US" pattern="[A-Za-z][A-Za-z]" maxlength={2} required disabled={payout.configured}/><p class="field-help">Use your legal residence's two-letter country code. Availability is checked before onboarding.</p><Button type="submit" disabled={busy || !payout.onboarding_enabled || !user.verified}>{payout.configured ? 'Continue verification' : 'Set up payout account'}<ArrowUpRight size={15}/></Button>{#if !payout.onboarding_enabled}<p class="field-help">Payout onboarding is not available yet.</p>{:else if !user.verified}<p class="field-help">Verify your email in account settings to continue.</p>{/if}</form></section><h2 class="jobs-section">Earnings activity</h2>{#each data.entries || [] as entry}<div class="record"><div><strong>{entry.description || entry.kind}</strong><small>{date(entry.created_at)}</small></div><span>{money(entry.amount_cents,data.currency)}</span></div>{:else}<p class="quiet-empty">Confirmed earnings and adjustments will appear here.</p>{/each}
      {:else if path === '/premium'||path === '/memberships'}
        <div class="page-heading"><h1>VideoFlow Premium</h1><p>One subscription for Premium videos across VideoFlow. Generation credits are purchased separately.</p></div>
        <section class="cloud-panel premium-panel"><Crown class="size-7 text-muted-foreground"/><h2>{data.active?'Your Premium subscription':'Unlock Premium content'}</h2>{#if data.active}<span class="status">{data.status || 'Active'}</span><p>Premium access is active{data.paid_through ? ` through ${date(data.paid_through)}` : ''}.</p>{:else}<p>Watch Premium videos from creators across the platform with one subscription.</p>{#if data.price_cents>0}<strong class="premium-price">{money(data.price_cents,data.currency)}<span>/month</span></strong>{/if}{#if !data.enabled}<div class="info-banner"><ShieldCheck class="size-5"/><p>Premium subscriptions are not available yet. Pricing and payment availability must be configured before checkout opens.</p></div>{/if}<Button disabled={busy||!data.enabled} onclick={subscribePremium}>{user?'Subscribe to Premium':'Sign in to subscribe'} <ArrowUpRight class="size-4"/></Button>{/if}{#if user&&data.status&&!['none',''].includes(data.status)}<Button variant="outline" disabled={busy} onclick={()=>action(async()=>{const result=await request('/premium/manage',{});window.location.assign(result.url);})}>Manage Premium <ArrowUpRight class="size-4"/></Button>{/if}<p class="field-help">Premium grants viewing access. It does not include studio generation credits or guarantee creator earnings.</p></section>
      {:else if path === '/settings'}
        <div class="page-heading"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1>Account settings</h1><p>Your identity across your studio and channel.</p></div><section class="cloud-panel account-panel"><h2>Personal details</h2><dl><div><dt>Name</dt><dd>{user.name}</dd></div><div><dt>Email address</dt><dd>{user.email}</dd></div><div><dt>Channel handle</dt><dd>@{user.handle}</dd></div><div><dt>Email verification</dt><dd>{user.verified ? 'Verified' : 'Verification pending'}</dd></div></dl>{#if !user.verified}<p class="field-help">Check your inbox for a verification email before using features that require a verified account.</p><Button variant="outline" disabled={busy} onclick={()=>action(async()=>{const result=await request('/auth/resend-verification',{email:user.email});developmentToken=result.development_token || '';notice='Verification instructions sent. Check your inbox.';})}>Resend verification email</Button><a href="/verify-email" class="field-help">Enter verification token</a>{#if developmentToken}<p class="field-help">Local development token: <code>{developmentToken}</code></p>{/if}{/if}<Button variant="outline" href="/channel">Edit channel profile <ArrowUpRight size={15}/></Button></section>
        <section class="cloud-panel account-panel jobs-section"><h2>Privacy & account control</h2><p class="field-help">Clear the viewing history used for your account. Your Premium subscription, purchases, and saved projects remain available.</p><Button variant="outline" disabled={busy} onclick={()=>{if(window.confirm('Clear your viewing history? This cannot be undone.'))action(async()=>{await request('/viewer/history',{},'DELETE');notice='Your viewing history has been cleared.';});}}>Clear viewing history</Button><div class="account-deletion"><h3>Request account deletion</h3><p class="field-help">This submits a deletion request and immediately signs you out of all sessions. Financial and legal records follow the platform retention policy; they are not deleted immediately.</p><Button variant="destructive" disabled={busy} onclick={()=>{if(window.confirm('Request account deletion and sign out of all sessions? Financial and legal records are retained under the platform policy.'))action(async()=>{await request('/account/deletion',{});user=null;await goto('/login');notice='Account deletion requested. You have been signed out of all sessions. Financial and legal records follow the platform retention policy.';});}}>Request account deletion</Button></div></section>
      {:else if path.startsWith('/watch/')}
        <div class="watch-layout"><div class="player">{#if playback}<VideoPlayer videoId={data.id || path.split('/')[2]} onerror={(message)=>{error=message;playback='';}}/>{:else}<Film size={48}/><p>{data.status === 'ready' || data.status === 'published' ? 'Ready when you are.' : `Video ${data.status || 'is being prepared'}`}</p><Button disabled={busy} onclick={()=>action(async()=>{playback='play';})}><Play size={17}/>Play video</Button>{/if}</div><div class="watch-title"><h1>{data.title || 'Video'}</h1><span class="status">AI-generated</span></div><p>{data.description}</p>{#if data.channel_handle || data.handle}<a href={`/channels/${data.channel_handle || data.handle}`} class="creator-link">@{data.channel_handle || data.handle}<ArrowUpRight size={15}/></a>{/if}<div class="report-section">{#if user}<button class="report-toggle" onclick={()=>showReport=!showReport}>{showReport ? 'Cancel report' : 'Report this video'}</button>{#if showReport}<form onsubmit={(e)=>{e.preventDefault();action(async()=>{await request(`/videos/${data.id || path.split('/')[2]}/report`,{reason:reportReason});notice='Report submitted for review.';showReport=false;reportReason='';});}}><label for="report-reason">Tell us what should be reviewed</label><Textarea id="report-reason" bind:value={reportReason} minlength={5} maxlength={2000} required rows={3}/><p class="field-help">Include details about a content policy or copyright concern. Reports are reviewed by the platform.</p><Button type="submit" variant="outline" disabled={busy || reportReason.trim().length < 5}>Submit report</Button></form>{/if}{:else}<a class="report-toggle" href="/login">Sign in to report a concern</a>{/if}</div></div>
      {:else if path.startsWith('/channels/')}
        <div class="channel-banner"><span class="channel-avatar">{(data.channel?.name || data.name || 'V').slice(0,1)}</span><div><h1>{data.channel?.name || data.name || path.split('/')[2]}</h1><p>@{data.channel?.handle || data.handle || path.split('/')[2]}</p></div></div><p class="channel-about">{data.channel?.description || data.description}</p><div class="community-actions"><span class="subtle">{data.followers ?? data.channel?.followers ?? '—'} followers</span>{#if user?.channel_id !== (data.id || data.channel?.id)}<Button variant="outline" disabled={busy || followed} onclick={()=>{if(!user){void goto('/login');return;}action(async()=>{await request(`/channels/${data.id || data.channel?.id}/follow`,{});followed=true;notice='You are now following this channel.';});}}><Heart size={16}/>{followed ? 'Following' : 'Follow for free'}</Button>{/if}</div><h2>Videos</h2><div class="video-grid">{#each data.videos || [] as video}<a class="video-tile" href={`/watch/${video.id}`}><div class="video-image">{#if video.thumbnail_url}<img src={video.thumbnail_url} alt=""/>{:else}<Film size={30}/>{/if}</div><h3>{video.title}</h3></a>{:else}<p class="quiet-empty">This creator hasn't published any public videos yet.</p>{/each}</div>
      {:else}<div class="cloud-empty"><Compass size={35}/><h1>A little off the beaten path.</h1><p>This page isn't part of your cloud studio.</p><Button href="/">Back to studio</Button></div>{/if}

    </main>
  </div>
</div>

{/if}
